pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with 1 ether
        vm.deal(address(c), 1 ether);
        // Non-owner calls sendTo with half the balance
        address nonOwner = address(0x123);
        vm.deal(nonOwner, 1 ether);
        vm.prank(nonOwner);
        // In reference: require msg.sender == owner fails => revert (c.balance unchanged)
        // In buggy: no owner check => transfer succeeds (c.balance becomes 0.5 ether)
        c.sendTo(nonOwner, 0.5 ether);
        // Assert that balance remained 1 ether (reference behavior)
        assertEq(address(c).balance, 1 ether);
    }
}

