pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up non-owner caller with ether
        address nonOwner = address(1);
        vm.deal(nonOwner, 0);

        // Record owner balance before
        address owner = address(this); // constructor sets msg.sender
        uint balanceBefore = address(owner).balance;

        // Non-owner calls sendTo(owner, 1 ether) – reference reverts, buggy succeeds
        vm.prank(nonOwner);
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.sendTo.selector, owner, 1 ether));

        if (!ok) {
            // Reference reverts, balance unchanged
            assertTrue(balanceBefore == address(owner).balance);
        } else {
            // Buggy contract succeeds, balance decreases (sends to self)
            assertTrue(balanceBefore == address(owner).balance + 1 ether);
        }
    }
}

