pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Owner is address(this) in Foundry test context
        address owner = address(this);
        address receiver = address(0); // zero address to trigger revert in reference
        uint amount = 1 wei;

        // Reference: sendTo reverts because receiver == address(0)
        // Buggy: sendTo also reverts because receiver == address(0)
        // We need a different scenario: use a non-zero receiver where reference would revert due to msg.sender check

        // Actually: reference requires msg.sender == owner, so owner can call
        // Buggy requires msg.sender != owner, so owner's call reverts
        // Thus: owner calls sendTo(someone, 1) - reference succeeds, buggy reverts

        // But we already tried that - find something else

        // The difference: reference has require(msg.sender == owner) so only owner can call
        // Buggy has require(msg.sender != owner) so only non-owner can call

        // Concrete: a non-owner (address(1)) calls sendTo(owner, 1 wei)
        // Reference: reverts because msg.sender (address(1)) != owner (address(this))
        // Buggy: succeeds because msg.sender (address(1)) != owner (address(this))
        // This changes address(c).balance - reference unchanged, buggy transfers 1 wei from owner to owner (no net change)

        vm.deal(address(1), 1 wei);
        vm.prank(address(1));
        try c.sendTo{value: 1 wei}(owner, 1 wei) {
            assertTrue(true); // shouldn't reach here in reference
        } catch {
            // Reference should revert
        }

        // Actually we need to assert something that differs
        // Let's use a different approach: compare balances after operation
        uint balanceBefore = address(c).balance;
        vm.deal(owner, 1 ether);
        vm.prank(owner);
        c.sendTo(address(1), 1 ether); // reference succeeds, buggy reverts
        bool succeeded = (address(c).balance == balanceBefore - 1 ether); // reference decreases, buggy unchanged
        assertTrue(succeeded);
    }
}

