pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // owner calls sendTo with receiver=address(1) and amount=0
        // reference: require(msg.sender==owner) OK, require(receiver!=address(0)) OK, require(amount>0) fails => revert
        // bug: require(msg.sender==owner) OK, require(receiver==address(0)) false => revert (same outcome, so this test diverges? Wait bug requires receiver==address(0), so receiver=address(1) makes require fail and revert too. Let me reconsider.)
        // Actually to witness divergence: bug require(receiver==address(0)) will fail for non-zero address, same as reference revert. I need a case where reference reverts but bug doesn't. That only happens with receiver=address(0) because bug passes require(receiver==address(0)) and then proceeds to transfer, while reference reverts. But the test already tried that. So I need another divergence.
        // Alternative: reference sends to non-zero address (receiver!=address(0)) and bug also sends to that address because bug's require(receiver==address(0)) would fail so bug reverts. That's also not new.
        // Actually the only observable difference is when receiver=address(0): reference reverts, bug sends. So the only way to diverge is that. But the prompt says that was already tried. I must pick a different concrete input. But the only difference in the mutant is flipping require(receiver != address(0)) to require(receiver == address(0)). That means:
        // - For receiver != address(0): reference succeeds, bug reverts (different outcome).
        // - For receiver == address(0): reference reverts, bug succeeds (different outcome).
        // Both are valid divergence scenarios. The already tried one was "reference reverts, bug sends ether and succeeds". So I'll pick the other: reference succeeds (sends ether to non-zero address), bug reverts. That requires a non-zero receiver and positive amount.
        // So: owner calls sendTo with receiver=address(1), amount=1 ether, sender has enough ether.
        address owner = address(this);
        vm.deal(owner, 1 ether);
        vm.prank(owner);
        bool ok;
        try c.sendTo(address(1), 1 ether) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: success => ok=true; Bug: reverts => ok=false
        assertTrue(ok);
    }
}

